import { LOGO_SPRITE, LOGO_VIEWS, type LogoId } from './logo-geometry';

// The Arrowbox logo (design 3a) for React islands. The drawings live in one cached sprite
// (public/brand/arrowbox-sprite.svg, generated by scripts/build-logo.mjs from IBM Plex Sans Bold
// outlines), so no path data ships in client JS; Logo.astro draws the same shapes inline on static
// pages. Ink is currentColor (the brand ink from .ab-logo, or the parent's colour); the orange is
// --logo-accent. Both inherit into the <use> copy, so CSS themes it.
//
//   <Logo />                          the wordmark at the 20px header size
//   <Logo size={56} />                the wordmark at a 56px font size (the 3px-line master)
//   <Logo variant="mark" size={32} /> the square mark (favicon glyph), 32px
//   <Logo tone="dark" />              colours for dark surfaces
//
// `size` is the wordmark's font size in px (the box and connector scale with it; up to 24px uses
// the compact drawing with the 2px line), or the mark's width and height.

export interface LogoProps {
  variant?: 'wordmark' | 'mark';
  size?: number;
  tone?: 'light' | 'dark';
  /** Accessible name. Pass null when visible text next to the logo already names it. */
  title?: string | null;
  className?: string;
}

/** Which drawing, its box at `size`, and how far the connector hangs below the box. */
export function logoBox(variant: LogoProps['variant'], size: number) {
  const id: LogoId = variant === 'mark' ? (size > 20 ? 'mark' : 'mark-small') : size > 24 ? 'wordmark' : 'wordmark-compact';
  const [w, h, box, s] = LOGO_VIEWS[id];
  const k = size / s;
  return { id, width: w * k, height: h * k, viewBox: `0 0 ${w} ${h}`, overhang: (h - box) * k };
}

export const logoClass = (tone?: string, className?: string) => `ab-logo${tone === 'dark' ? ' ab-logo--dark' : ''}${className ? ` ${className}` : ''}`;

export default function Logo({ variant, size = variant === 'mark' ? 32 : 20, tone, title = 'Arrowbox', className }: LogoProps) {
  const b = logoBox(variant, size);
  return (
    <svg
      className={logoClass(tone, className)}
      width={b.width}
      height={b.height}
      viewBox={b.viewBox}
      style={b.overhang ? { marginBottom: -b.overhang } : undefined}
      role={title ? 'img' : undefined}
      aria-label={title ?? undefined}
      aria-hidden={title ? undefined : true}
    >
      <use href={`${LOGO_SPRITE}#${b.id}`} />
    </svg>
  );
}
